<?php

declare(strict_types=1);

namespace App\Crud;

/**
 * Definición declarativa de una tabla del esquema: clave, columnas y orden.
 * La clave puede ser identidad numérica (GENERATED BY DEFAULT AS IDENTITY) o
 * UUID (CHAR(32) generado por la aplicación).
 */
final readonly class Entidad
{
    /** @var array<string, Campo> */
    public array $campos;

    /** @param list<Campo> $campos sin la clave */
    public function __construct(
        public string $tabla,
        public string $clave,
        array $campos,
        public bool $claveUuid = false,
        public ?string $orden = null,
    ) {
        $porNombre = [];
        foreach ($campos as $campo) {
            $porNombre[$campo->nombre] = $campo;
        }
        $this->campos = $porNombre;
    }

    /** Columnas de la respuesta, con la clave primero. */
    public function columnasSelect(string $alias = 't'): string
    {
        $columnas = ["{$alias}.\"{$this->clave}\""];
        foreach ($this->campos as $nombre => $campo) {
            $columnas[] = "{$alias}.\"{$campo->columnaBd()}\"".($campo->columnaBd() === $nombre ? '' : " AS \"{$nombre}\"");
        }

        return implode(', ', $columnas);
    }

    /** Columna en la base de un campo (o el mismo nombre). */
    public function columna(string $nombre): string
    {
        return isset($this->campos[$nombre]) ? $this->campos[$nombre]->columnaBd() : $nombre;
    }

    public function campoClave(): Campo
    {
        return Campo::salida($this->clave, $this->claveUuid ? Campo::UUID : Campo::ENTERO);
    }
}
